    private void linking() throws Exception {
        checkpoint = "GOOGLE_SIMULATED_CONCURRENT_LINK_AND_HISTORICAL_UID";
        var id = users.preProvisionGoogle( "Concurrent", "race@t029.example.test" );
        var token = googleToken( "race@t029.example.test", "t029-race", true );
        var start = new CountDownLatch( 1 );
        assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( Long.class ).single() ).isZero();
        try ( var validity = Observation.clock.sharedValidityInstant();
                var pool = Executors.newFixedThreadPool( 4 );
                var blocker = application.getBean( "firebaseSecurityDataSource", DataSource.class ).getConnection() ) {
            blocker.setAutoCommit( false );
            int blockerPid;
            try ( var statement = blocker.prepareStatement(
                    "SELECT pg_backend_pid() FROM security.usuario WHERE id_usuario=? FOR UPDATE" ) ) {
                statement.setObject( 1, id );
                try ( var rows = statement.executeQuery() ) {
                    assertThat( rows.next() ).isTrue();
                    blockerPid = rows.getInt( 1 );
                }
            }
            var jobs = java.util.stream.IntStream.range( 0, 4 ).mapToObj( index -> pool.submit( () -> {
                start.await();
                return expect( "GET", "/api/auth/me", token, null, null, 200 );
            } ) ).toList();
            start.countDown();
            try {
                // The fixture holds only the pending row. Native SDK transactions must reach
                // its FOR UPDATE and advisory locks before any identity can be committed.
                long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos( 10 );
                List<LinkWait> waits;
                do {
                    waits = nativeLinkWaits( blockerPid );
                    if ( waits.size() >= 2 ) {
                        break;
                    }
                    Thread.sleep( 50 );
                } while ( System.nanoTime() < deadline );
                System.out.println( "T029 LINK_OVERLAP blocker=" + blockerPid + " waiters=" + waits );
                assertThat( waits ).as( "native first-link SQL transactions overlap before fixture release" )
                        .hasSizeGreaterThanOrEqualTo( 2 ).allSatisfy( wait -> {
                            assertThat( wait.transaction() ).isTrue();
                            assertThat( wait.pid() ).isNotEqualTo( blockerPid );
                        } );
                assertThat( waits.stream().map( LinkWait::pid ).distinct().count() ).isEqualTo( waits.size() );
                assertThat( waits.stream().map( LinkWait::kind ).toList() ).contains( "ROW", "ADVISORY" );
                assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                        .param( "id", id ).query( Long.class ).single() ).isZero();
                assertThat( jdbc.sql( "SELECT cd_elegibilidade FROM security.usuario WHERE id_usuario=:id" )
                        .param( "id", id ).query( String.class ).single() ).isEqualTo( "GOOGLE_PENDING" );
                assertThat( jobs ).allSatisfy( job -> assertThat( job.isDone() ).isFalse() );
            } finally {
                blocker.rollback();
            }
            for ( var job : jobs ) {
                assertThat( job.get( 30, TimeUnit.SECONDS ) ).contains( id.toString() );
            }
        }
        assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( Long.class ).single() ).isOne();
        assertThat( jdbc.sql( "SELECT cd_elegibilidade FROM security.usuario WHERE id_usuario=:id" )
                .param( "id", id ).query( String.class ).single() ).isEqualTo( "BOUND" );
        String uid = application.getBean( IdTokenVerifier.class ).verify( token ).uid();
        assertThat( jdbc.sql( "SELECT cd_sujeito_externo FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( String.class ).single() ).isEqualTo( uid );
        assertThat( jdbc.sql( "SELECT count(*) FROM security.evento_seguranca "
                + "WHERE id_usuario=:id AND cd_evento='GOOGLE_IDENTITY_LINKED'" )
                .param( "id", id ).query( Long.class ).single() ).isOne();
        System.out.println( "T029 LINK_WINNER requests=4 identities=1 linkedEvents=1 state=BOUND" );
        jdbc.sql( "UPDATE security.usuario_identidade SET dt_fim=dt_inicio WHERE id_usuario=:id" ).param( "id", id )
                .update();
        expect( "GET", "/api/auth/me", token, null, null, 403 );
        assertThatThrownBy( () -> jdbc.sql( "INSERT INTO security.usuario_identidade SELECT :id,:user,"
                + "id_provedor_identidade,cd_emissor,cd_sujeito_externo,cd_email_identidade,dt_inicio,NULL "
                + "FROM security.usuario_identidade WHERE id_usuario=:owner" ).param( "id", UUID.randomUUID() )
                .param( "user", alice ).param( "owner", id ).update() )
