    }

    private record LinkWait(int pid, String kind, String blockers, boolean transaction) {
    }

    private List<LinkWait> nativeLinkWaits( int blockerPid ) {
        // Follow the actual PG wait graph: the row-lock waiter owns the SDK advisory
        // lock, so other first-link transactions wait indirectly on the fixture.
        return jdbc.sql( """
                WITH RECURSIVE waiting AS (
                    SELECT pid,query,xact_start,pg_blocking_pids(pid) AS blockers
                    FROM pg_stat_activity WHERE datname=current_database()
                    AND state='active' AND wait_event_type='Lock'
                ), connected(pid) AS (
                    SELECT :blocker
                    UNION
                    SELECT w.pid FROM waiting w JOIN connected c ON c.pid=ANY(w.blockers)
                )
                SELECT w.pid,CASE WHEN w.query ILIKE '%FOR UPDATE%' THEN 'ROW' ELSE 'ADVISORY' END AS kind,
                    w.blockers::text,w.xact_start IS NOT NULL AS transaction
                FROM waiting w JOIN connected c ON c.pid=w.pid
                WHERE (w.query ILIKE '%security.usuario%FOR UPDATE%'
                    OR w.query ILIKE '%pg_advisory_xact_lock%') ORDER BY w.pid
                """ ).param( "blocker", blockerPid )
                .query( ( rs, row ) -> new LinkWait( rs.getInt( 1 ), rs.getString( 2 ), rs.getString( 3 ),
                        rs.getBoolean( 4 ) ) )
                .list();
    }

