        checkpoint = "NATIVE_SERVLET_REUSED_THREAD_SUCCESS_DENIAL_EXCEPTION_CLEANUP";
        assertThat( tomcatProtocol().getMaxThreads() ).as( "segregated cleanup phase worker limit" ).isOne();
        Observation.requests.clear();
