    private void providerOutage() throws Exception {
        checkpoint = "OWNED_PROVIDER_OUTAGE_503_AND_DURABLE_LOCAL_BLOCK";
        String container = System.getenv( "T029_EMULATOR_CONTAINER" );
        assertThat( container ).matches( "[a-f0-9]{64}" );
        var id = users.preProvisionGoogle( "Outage", "outage@t029.example.test" );
