        docker( "exec", container, "firebase", "emulators:export", "/data/export", "--project", "demo-gems",
                "--force" );
        publishedPort( container );
        docker( "stop", "--time", "30", container );
        try {
            expect( "GET", "/api/auth/me", aliceToken, null, null, 503 );
            users.suspend( id );
            drain();
            assertThat( jdbc.sql( "SELECT dt_fim IS NOT NULL FROM security.usuario WHERE id_usuario=:id" )
