                    .param( "id", id ).query( Long.class ).single() ).isPositive();
        } finally {
            docker( "start", container );
            publishedPort( container );
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos( 45 );
            while ( true ) {
                try {
                    if ( client.send(
                            HttpRequest.newBuilder( URI.create( emulator ) ).timeout( Duration.ofSeconds( 2 ) ).build(),
                            HttpResponse.BodyHandlers.discarding() ).statusCode() == 200 ) {
                        break;
                    }
                } catch ( java.io.IOException unavailable ) {
                    // Only the resource owned by this Testcontainers fixture is restarted.
                }
                assertThat( System.nanoTime() ).as( "owned Emulator readiness at " + emulator ).isLessThan( deadline );
                Thread.sleep( 100 );
            }
        }
        expect( "GET", "/api/auth/me", token, null, null, 401 );
        String renewed = googleToken( "outage@t029.example.test", "t029-outage", true );
        assertThat( verifier.verify( renewed ).uid().equals( uid ) ).as( "restored provider UID unchanged" ).isTrue();
        expect( "GET", "/api/auth/me", renewed, null, null, 403 );
