            assertThat( browser.waitFor( 10, TimeUnit.MINUTES ) ).isTrue();
            return browser.exitValue();
        } finally {
            if ( browser.isAlive() ) {
                browser.descendants().forEach( ProcessHandle::destroy );
                browser.destroyForcibly();
