    private String googleToken( String email, String subject, boolean verified ) throws Exception {
        var encoder = Base64.getUrlEncoder().withoutPadding();
        String token = encoder.encodeToString( "{\"alg\":\"none\"}".getBytes( StandardCharsets.UTF_8 ) ) + "."
                + encoder.encodeToString(
                        JSON.toString( Map.of( "sub", subject, "email", email, "email_verified", verified,
                                "name", "Simulated Google" ) ).getBytes( StandardCharsets.UTF_8 ) )
                + ".";
        return (String) emulator( "accounts:signInWithIdp",
                Map.of( "postBody", "id_token=" + token + "&providerId=google.com",
                        "requestUri", "http://localhost", "returnSecureToken", true ),
                false ).get( "idToken" );
    }

    private Map<?, ?> emulator( String route, Map<String, Object> payload, boolean administrator ) throws Exception {
        var builder = HttpRequest.newBuilder( URI.create( emulator + "/identitytoolkit.googleapis.com/v1/" + route
                + "?key=emulator-only" ) ).header( "Content-Type", "application/json" )
                .timeout( Duration.ofSeconds( 10 ) );
        if ( administrator ) {
            builder.header( "Authorization", "Bearer owner" );
        }
        var response = client.send(
                builder.POST( HttpRequest.BodyPublishers.ofString( JSON.toString( payload ) ) ).build(),
                HttpResponse.BodyHandlers.ofString() );
        assertThat( response.statusCode() ).as( "emulator " + route ).isEqualTo( 200 );
        return JSON.fromString( response.body(), Map.class );
    }

    private String expect( String method, String path, String token, String alias, String body, int status )
            throws Exception {
        var builder = HttpRequest.newBuilder( URI.create( api + path ) ).timeout( Duration.ofSeconds( 20 ) )
                .header( "Content-Type", "application/json" );
        if ( token != null ) {
            builder.header( "Authorization", "Bearer " + token );
        }
        if ( alias != null ) {
            builder.header( "X-Tenant-Alias", alias );
        }
        var response = client.send( builder.method( method, body == null
                ? HttpRequest.BodyPublishers.noBody()
                : HttpRequest.BodyPublishers.ofString( body ) ).build(), HttpResponse.BodyHandlers.ofString() );
        assertThat( response.statusCode() ).as( method + " " + path ).isEqualTo( status );
        return response.body();
    }

    private void passed() {
        System.out.println( "T029 PASS " + checkpoint );
    }
