    public static void main( String[] args ) {
        EndToEndSupport suite = null;
        try ( var context = new SpringApplicationBuilder( AppApplication.class, Observation.class ).run(
                "--spring.config.location=" + Path.of( "src/main/resources/application.yml" ).toAbsolutePath().toUri(),
                "--spring.profiles.active=test", "--server.port=0", "--logging.level.root=OFF",
                "--spring.main.banner-mode=off", "--app.security.cors.allowed-origins=http://localhost:4301",
                "--spring.threads.virtual.enabled=false", "--server.tomcat.threads.max=1",
                "--server.tomcat.threads.min-spare=1" ) ) {
            suite = new EndToEndSupport( context );
            suite.seed();
            suite.http();
            suite.constraints();
            suite.threadCleanup();
            suite.concurrentWorkers();
            suite.linking();
            suite.validityChain();
            suite.negativeGates();
            suite.providerOutage();
            suite.lifecycle();
            suite.remoteAckRace();
            suite.browser();
            suite.membership();
            System.out.println( "T029 SUITE PASS" );
        } catch ( Throwable failure ) {
            if ( failure instanceof java.util.concurrent.ExecutionException
                    && failure.getCause() instanceof AssertionError ) {
                failure = failure.getCause();
            }
            // Never print remote exception causes, bearer values, passwords or reset links.
            System.err.println( "T029 FAIL " + (suite == null ? "STARTUP" : suite.checkpoint) + " "
                    + failure.getClass().getSimpleName() );
            if ( failure instanceof AssertionError && failure.getMessage() != null ) {
                System.err.println( "T029 ASSERT " + failure.getMessage()
                        .replaceAll( "(?i)(Bearer\\s+|eyJ)[^\\s]+", "[REDACTED]" ).replace( '\n', ' ' )
                        .replace( '\r', ' ' ) );
            }
            System.exit( 1 );
        }
    }

    private void seed() throws Exception {
        checkpoint = "SEED";
        alice = users.provisionPassword( "Alice", "alice@t029.example.test" );
        drain();
        String uid = jdbc.sql( "SELECT cd_uid_planejado FROM security.usuario WHERE id_usuario=:id" )
                .param( "id", alice ).query( String.class ).single();
        emulator( "accounts:update", Map.of( "localId", uid, "password", password, "targetProjectId", "demo-gems" ),
                true );
        aliceToken = passwordToken( "alice@t029.example.test" );
        bob = users.preProvisionGoogle( "Bob", "bob@t029.example.test" );
        bobToken = googleToken( "bob@t029.example.test", "t029-google-bob", true );
        expect( "GET", "/api/auth/me", bobToken, null, null, 200 );
        alpha = tenants.create( "alpha", "Alpha" );
        beta = tenants.create( "beta", "Beta" );
        provisioner.provision( alpha, 1, new SampleTenantMigration() );
        provisioner.provision( beta, 1, new SampleTenantMigration() );
        aliceMember = tenants.addMember( alpha, alice );
        bobAlpha = tenants.addMember( alpha, bob );
        bobBeta = tenants.addMember( beta, bob );
        for ( String action : catalog.tenantActions() ) {
            grants.grant( GrantAdministration.Target.MEMBER, alpha, bobAlpha, action );
            grants.grant( GrantAdministration.Target.MEMBER, beta, bobBeta, action );
            if ( !action.equals( "REVOGAR_GRANT" ) ) {
                grants.grant( GrantAdministration.Target.MEMBER, alpha, aliceMember, action );
            }
        }
        for ( String action : catalog.globalActions() ) {
            grants.grantGlobal( bob, action );
        }
        for ( String alias : List.of( "alpha", "beta" ) ) {
            jdbc.sql( "CREATE TABLE tenant_" + alias
                    + ".scope_probe (id_probe UUID PRIMARY KEY, nm_label TEXT NOT NULL)" ).update();
            jdbc.sql( "INSERT INTO tenant_" + alias + ".scope_probe VALUES(:id,:name)" )
                    .param( "id", UUID.fromString( SAME_ID ) )
                    .param( "name", alias.equals( "alpha" ) ? "Alpha" : "Beta" ).update();
        }
        passed();
    }

