    private void linking() throws Exception {
        checkpoint = "GOOGLE_SIMULATED_CONCURRENT_LINK_AND_HISTORICAL_UID";
        var id = users.preProvisionGoogle( "Concurrent", "race@t029.example.test" );
        var token = googleToken( "race@t029.example.test", "t029-race", true );
        var start = new CountDownLatch( 1 );
        assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( Long.class ).single() ).isZero();
        try ( var validity = Observation.clock.sharedValidityInstant();
                var pool = Executors.newFixedThreadPool( 4 );
                var blocker = application.getBean( "firebaseSecurityDataSource", DataSource.class ).getConnection() ) {
            blocker.setAutoCommit( false );
            int blockerPid;
            try ( var statement = blocker.prepareStatement(
                    "SELECT pg_backend_pid() FROM security.usuario WHERE id_usuario=? FOR UPDATE" ) ) {
                statement.setObject( 1, id );
                try ( var rows = statement.executeQuery() ) {
                    assertThat( rows.next() ).isTrue();
                    blockerPid = rows.getInt( 1 );
                }
            }
            var jobs = java.util.stream.IntStream.range( 0, 4 ).mapToObj( index -> pool.submit( () -> {
                start.await();
                return expect( "GET", "/api/auth/me", token, null, null, 200 );
            } ) ).toList();
            start.countDown();
            try {
                // The fixture holds only the pending row. Native SDK transactions must reach
                // its FOR UPDATE and advisory locks before any identity can be committed.
                long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos( 10 );
                List<LinkWait> waits;
                do {
                    waits = nativeLinkWaits( blockerPid );
                    if ( waits.size() >= 2 ) {
                        break;
                    }
                    Thread.sleep( 50 );
                } while ( System.nanoTime() < deadline );
                System.out.println( "T029 LINK_OVERLAP blocker=" + blockerPid + " waiters=" + waits );
                assertThat( waits ).as( "native first-link SQL transactions overlap before fixture release" )
                        .hasSizeGreaterThanOrEqualTo( 2 ).allSatisfy( wait -> {
                            assertThat( wait.transaction() ).isTrue();
                            assertThat( wait.pid() ).isNotEqualTo( blockerPid );
                        } );
                assertThat( waits.stream().map( LinkWait::pid ).distinct().count() ).isEqualTo( waits.size() );
                assertThat( waits.stream().map( LinkWait::kind ).toList() ).contains( "ROW", "ADVISORY" );
                assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                        .param( "id", id ).query( Long.class ).single() ).isZero();
                assertThat( jdbc.sql( "SELECT cd_elegibilidade FROM security.usuario WHERE id_usuario=:id" )
                        .param( "id", id ).query( String.class ).single() ).isEqualTo( "GOOGLE_PENDING" );
                assertThat( jobs ).allSatisfy( job -> assertThat( job.isDone() ).isFalse() );
            } finally {
                blocker.rollback();
            }
            for ( var job : jobs ) {
                assertThat( job.get( 30, TimeUnit.SECONDS ) ).contains( id.toString() );
            }
        }
        assertThat( jdbc.sql( "SELECT count(*) FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( Long.class ).single() ).isOne();
        assertThat( jdbc.sql( "SELECT cd_elegibilidade FROM security.usuario WHERE id_usuario=:id" )
                .param( "id", id ).query( String.class ).single() ).isEqualTo( "BOUND" );
        String uid = application.getBean( IdTokenVerifier.class ).verify( token ).uid();
        assertThat( jdbc.sql( "SELECT cd_sujeito_externo FROM security.usuario_identidade WHERE id_usuario=:id" )
                .param( "id", id ).query( String.class ).single() ).isEqualTo( uid );
        assertThat( jdbc.sql( "SELECT count(*) FROM security.evento_seguranca "
                + "WHERE id_usuario=:id AND cd_evento='GOOGLE_IDENTITY_LINKED'" )
                .param( "id", id ).query( Long.class ).single() ).isOne();
        System.out.println( "T029 LINK_WINNER requests=4 identities=1 linkedEvents=1 state=BOUND" );
        jdbc.sql( "UPDATE security.usuario_identidade SET dt_fim=dt_inicio WHERE id_usuario=:id" ).param( "id", id )
                .update();
        expect( "GET", "/api/auth/me", token, null, null, 403 );
        assertThatThrownBy( () -> jdbc.sql( "INSERT INTO security.usuario_identidade SELECT :id,:user,"
                + "id_provedor_identidade,cd_emissor,cd_sujeito_externo,cd_email_identidade,dt_inicio,NULL "
                + "FROM security.usuario_identidade WHERE id_usuario=:owner" ).param( "id", UUID.randomUUID() )
                .param( "user", alice ).param( "owner", id ).update() )
                .isInstanceOf( DataIntegrityViolationException.class ).satisfies( failure -> assertThat(
                        ((java.sql.SQLException) ((DataIntegrityViolationException) failure).getMostSpecificCause())
                                .getSQLState() )
                        .isEqualTo( "23505" ) );
        System.out.println( "T029 LINK_UNIQUE duplicateHistoricalUidRejected=23505" );
        users.preProvisionGoogle( "Unverified", "unverified@t029.example.test" );
        expect( "GET", "/api/auth/me", googleToken( "unverified@t029.example.test", "t029-unverified", false ), null,
                null,
                403 );
        passed();
    }

    private record LinkWait(int pid, String kind, String blockers, boolean transaction) {
    }

    private List<LinkWait> nativeLinkWaits( int blockerPid ) {
        // Follow the actual PG wait graph: the row-lock waiter owns the SDK advisory
        // lock, so other first-link transactions wait indirectly on the fixture.
        return jdbc.sql( """
                WITH RECURSIVE waiting AS (
                    SELECT pid,query,xact_start,pg_blocking_pids(pid) AS blockers
                    FROM pg_stat_activity WHERE datname=current_database()
                    AND state='active' AND wait_event_type='Lock'
                ), connected(pid) AS (
                    SELECT :blocker
                    UNION
                    SELECT w.pid FROM waiting w JOIN connected c ON c.pid=ANY(w.blockers)
                )
                SELECT w.pid,CASE WHEN w.query ILIKE '%FOR UPDATE%' THEN 'ROW' ELSE 'ADVISORY' END AS kind,
                    w.blockers::text,w.xact_start IS NOT NULL AS transaction
                FROM waiting w JOIN connected c ON c.pid=w.pid
                WHERE (w.query ILIKE '%security.usuario%FOR UPDATE%'
                    OR w.query ILIKE '%pg_advisory_xact_lock%') ORDER BY w.pid
                """ ).param( "blocker", blockerPid )
                .query( ( rs, row ) -> new LinkWait( rs.getInt( 1 ), rs.getString( 2 ), rs.getString( 3 ),
                        rs.getBoolean( 4 ) ) )
                .list();
    }

    private void lifecycle() throws Exception {
        checkpoint = "OUTBOX_RESTART_REMOTE_DISABLE_REVOKE_LATEST_VERSION";
        var id = users.provisionPassword( "Lifecycle", "lifecycle@t029.example.test" );
        // Persisted expired claim survives constructing a new worker instance.
        jdbc.sql(
                "UPDATE security.comando_identidade SET cd_estado='CLAIMED',cd_claim=:claim,dt_lease=now()-interval '1 minute'"
                        + " WHERE id_usuario=:id" )
                .param( "claim", UUID.randomUUID() ).param( "id", id ).update();
        drain();
        var uid = jdbc.sql( "SELECT cd_uid_planejado FROM security.usuario WHERE id_usuario=:id" ).param( "id", id )
                .query( String.class ).single();
        emulator( "accounts:update", Map.of( "localId", uid, "password", password, "targetProjectId", "demo-gems" ),
                true );
        var token = passwordToken( "lifecycle@t029.example.test" );
        expect( "GET", "/api/auth/me", token, null, null, 200 );
        users.suspend( id );
        expect( "GET", "/api/auth/me", token, null, null, 403 );
        drain();
        assertThat( admin.getUser( uid ).disabled() ).isTrue();
        expect( "GET", "/api/auth/me", token, null, null, 401 );
        users.requestReactivation( id );
        users.cancelReactivation( id );
        drain();
        assertThat( admin.getUser( uid ).disabled() ).isTrue();
        assertThat( jdbc.sql( "SELECT count(*) FROM security.comando_identidade WHERE id_usuario=:id"
                + " AND cd_tipo='ENABLE' AND cd_estado='OBSOLETE'" ).param( "id", id ).query( Long.class ).single() )
                .isOne();
        assertThat(
                jdbc.sql( "SELECT count(*) FROM security.usuario_role_global WHERE id_usuario=:id AND dt_fim IS NULL" )
                        .param( "id", id ).query( Long.class ).single() )
                .isZero();
        // Revocation with a deterministic later auth_time boundary, still using the real adapter.
        emulator( "accounts:update", Map.of( "localId", uid, "disableUser", false, "validSince",
                String.valueOf( java.time.Instant.now().getEpochSecond() + 10 ), "targetProjectId", "demo-gems" ),
                true );
        expect( "GET", "/api/auth/me", token, null, null, 401 );
        passed();
    }

    private void remoteAckRace() throws Exception {
        checkpoint = "NATIVE_ADMIN_CREATE_ACK_CAS_INFLIGHT";
        var id = users.provisionPassword( "Remote race", "remote-race@t029.example.test" );
        var reached = new CountDownLatch( 1 );
        var release = new CountDownLatch( 1 );
        var forwarding = new FirebaseAdminGateway() {
            public User getUser( String uid ) {
                return admin.getUser( uid );
            }
            public User createUser( String uid, String email, String name ) {
                var created = admin.createUser( uid, email, name );
                reached.countDown();
                try {
                    if ( !release.await( 20, TimeUnit.SECONDS ) )
                        throw new IllegalStateException( "RACE_TIMEOUT" );
                } catch ( InterruptedException failure ) {
                    Thread.currentThread().interrupt();
                    throw new IllegalStateException( "RACE_INTERRUPTED" );
                }
                return created;
            }
            public void setDisabled( String uid, boolean disabled ) {
                admin.setDisabled( uid, disabled );
            }
            public void revokeRefreshTokens( String uid ) {
                admin.revokeRefreshTokens( uid );
            }
            public String passwordResetLink( String email ) {
                throw new UnsupportedOperationException();
            }
        };
        var worker = new JdbcIdentityCommandWorker( jdbc,
                application.getBean( "firebaseSecurityTransactions", TransactionTemplate.class ),
                application.getBean( SecurityEventSink.class ),
                application.getBean( "firebaseSecurityDataSource", DataSource.class ), forwarding,
                application.getBean( Clock.class ), Duration.ofMinutes( 2 ) );
