    nextToken.resolve('new');
    await tick();
    http.expectNone(environment.apiBaseUrl + '/demo-registros');
    const request = http.expectOne(environment.apiBaseUrl + '/auth/me');
    expect(request.request.headers.get('Authorization')).toBe('Bearer new');
