    http.expectNone(environment.apiBaseUrl + '/tenant-request-fixtures/1');
  });
  it('deveSelecionarBetaViaServico_quandoAlphaAguardaTokenComUILocked', async () => {
    await ready();
    const pending = deferred<string>();
    const original = user.getIdToken;
    user.getIdToken = () => {
      user.getIdToken = original;
      return pending.promise;
    };
    const alpha = auth.selectTenant('alpha');
    await tick();
    expect(auth.loading()).toBe(true);
    const snapshot = auth.capture();
    const beta = auth.selectTenant('beta');
