async function googleLogin(page: Page, navigate = true): Promise<void> {
  if (navigate) await page.goto('/login');
  const popupPromise = page.waitForEvent('popup');
  await page.getByRole('button', { name: 'Continuar com Google' }).click();
  const popup = await popupPromise;
  await popup.waitForLoadState();
  // The official Emulator page simulates OAuth; no real Google account is used.
  const existing = popup.getByText('bob@t029.example.test', { exact: false }).first();
  if (await existing.isVisible()) {
    await existing.click();
  } else {
    await popup.getByRole('button', { name: /Add new account/i }).click();
    await popup.getByLabel(/Email/i).fill('bob@t029.example.test');
    await popup.getByLabel(/Display name/i).fill('Bob');
    await popup.getByRole('button', { name: /Sign in with Google/i }).click();
  }
  await expect(page.getByRole('heading', { name: 'Escolha sua empresa' })).toBeVisible();
}

