for (const invalidation of ['switch', 'logout']) {
  test(`${invalidation} during actual native token await prevents old Alpha context request`, async ({
    page,
  }) => {
    await googleLogin(page);
    await page.getByRole('button', { name: 'Alpha', exact: true }).click();
    await expect(page).toHaveURL(/\/$/);
    await delayCurrentNativeToken(page);
    let oldRequests = 0;
    page.on('request', (request) => {
      if (
        request.url() === `${api}/auth/context` &&
        request.headers()['x-tenant-alias'] === 'alpha'
      )
        oldRequests++;
    });
    await page.evaluate(() => {
      const auth = (globalThis as Runtime).ng.getComponent(
        document.querySelector('app-root')!,
      ).auth;
      void auth.selectTenant('alpha').catch(() => {});
    });
    await expect
      .poll(() => page.evaluate(() => (globalThis as Runtime).t029Token?.started))
      .toBe(true);
    try {
      if (invalidation === 'switch') {
        await expect(page.getByRole('button', { name: 'Trocar empresa' })).toBeDisabled();
        // Concurrent service selection invalidates the pending epoch while the UI stays locked.
        await page.evaluate(async () => {
          const root = (globalThis as Runtime).ng.getComponent(document.querySelector('app-root')!);
          await root.auth.selectTenant('beta');
        });
        await expect
          .poll(() =>
            page.evaluate(
              () =>
                (globalThis as Runtime).ng
                  .getComponent(document.querySelector('app-root')!)
                  .auth.currentTenant()?.alias,
            ),
          )
          .toBe('beta');
      } else {
        await page.getByTitle('Encerrar sessão', { exact: true }).click();
        await expect(page).toHaveURL(/\/login$/);
      }
    } finally {
      await releaseNativeToken(page);
    }
    await page.waitForTimeout(300);
    expect(oldRequests).toBe(0);
    expect(
      await page.evaluate(
        () =>
          (globalThis as Runtime).ng
            .getComponent(document.querySelector('app-root')!)
            .auth.currentTenant()?.alias ?? null,
      ),
    ).toBe(invalidation === 'switch' ? 'beta' : null);
  });
}

