import { Route, Routes } from '@angular/router';
import { routes } from '../../app.routes';
import { roleGuard } from './role.guard';
import { authGuard } from './auth.guard';
import { belongsToScope } from '../auth/acoes';
async function visit(routes: Routes): Promise<number> {
  let count = 0;
  for (const route of routes) {
    if (route.canActivate?.includes(roleGuard)) {
      count++;
      const data = route.data;
      expect(data?.['roles']?.length).toBeGreaterThan(0);
      expect(['global', 'tenant']).toContain(data?.['authorizationScope']);
      for (const action of data?.['roles'] ?? [])
        expect(belongsToScope(action, data!['authorizationScope'])).toBe(true);
    }
    if (route.children) count += await visit(route.children);
    if (route.loadChildren) {
      const loaded = await (route.loadChildren as () => Promise<{ default: Routes }>)();
      count += await visit(loaded.default);
    }
  }
  return count;
}
describe('Cobertura real de rotas lazy', () => {
  it('deveExigirRolesEscopo_quandoResolveTodasAsFeatures', async () => {
    expect(await visit(routes)).toBe(0);
    expect(routes.find((route) => route.path === 'tenants')?.canActivate).toContain(authGuard);
    expect(routes.find((route) => route.path === '')?.canActivate).toContain(authGuard);
  });
  it('deveValidarAcaoReal_quandoFixtureTemGuardEMetadataCorretos', async () => {
    expect(
      await visit([
        {
          path: 'fixture',
          canActivate: [roleGuard],
          data: {
            roles: ['CONSULTAR_PROPRIO_CONTEXTO_TENANT'],
            authorizationScope: 'tenant',
          },
        },
      ]),
    ).toBe(1);
  });
  it('deveRecusarRolesEScopeInvalidos_quandoFixtureExercitaVisit', async () => {
    for (const data of [
      {},
      { roles: [], authorizationScope: 'tenant' },
      { roles: ['CONSULTAR_PROPRIO_CONTEXTO_TENANT'], authorizationScope: 'invalid' },
      { roles: ['CONSULTAR_PROPRIA_CONTA'], authorizationScope: 'tenant' },
    ]) {
      await expect(visit([{ path: 'fixture', canActivate: [roleGuard], data }])).rejects.toThrow();
    }
  });
});
